export class AgentInbox {

 constructor(state, env) {

 this.state = state;

 this.sessions = [];

 }



 async fetch(request) {

 const url = new URL(request.url);

 if (request.headers.get('Upgrade') === 'websocket') {

 return this.handleWebSocket(request, url);

 }

 switch (url.pathname) {

 case '/send': return this.handleSend(request);

 case '/inbox': return this.handleInbox(url);

 case '/history': return this.handleHistory(url);

 case '/agents': return this.handleAgents();

 case '/health': return new Response('OK');

 default: return new Response('Not Found', { status: 404 });

 }

 }



 async handleWebSocket(request, url) {

 const agentId = url.searchParams.get('agent');

 const agentName = url.searchParams.get('name') || agentId;

 if (!agentId) return new Response('Missing agent', { status: 400 });



 const [client, server] = Object.values(new WebSocketPair());

 this.sessions.push({ ws: server, agentId, agentName, connectedAt: Date.now() });

 server.accept();



 server.send(JSON.stringify({ type: 'system', content: `Connected as ${agentName}`, timestamp: Date.now() }));



 server.addEventListener('message', async (event) => {

 try {

 const data = JSON.parse(event.data);

 const message = {

 id: this.generateId(), sender: agentId, senderName: agentName,

 content: data.content, threadId: data.threadId || 'general',

 timestamp: Date.now(), type: data.type || 'message',

 replyTo: data.replyTo || null, metadata: data.metadata || {}

 };

 await this.storeMessage(message);

 this.broadcast(message, agentId);

 } catch (err) {

 server.send(JSON.stringify({ type: 'error', content: err.message }));

 }

 });



 server.addEventListener('close', () => {

 this.sessions = this.sessions.filter(s => s.ws !== server);

 });



 return new Response(null, { status: 101, webSocket: client });

 }



 async handleSend(request) {

 const data = await request.json();

 const message = {

 id: this.generateId(), sender: data.sender, senderName: data.senderName || data.sender,

 content: data.content, threadId: data.threadId || 'general',

 timestamp: Date.now(), type: data.type || 'message',

 replyTo: data.replyTo || null, metadata: data.metadata || {}

 };

 await this.storeMessage(message);

 this.broadcast(message, data.sender);

 return new Response(JSON.stringify({ success: true, messageId: message.id }),

 { headers: { 'Content-Type': 'application/json' } });

 }



 async handleInbox(url) {

 const agentId = url.searchParams.get('agent');

 const since = parseInt(url.searchParams.get('since') || '0');

 if (!agentId) return new Response('Missing agent', { status: 400 });

 const messages = await this.getMessagesSince(since);

 return new Response(JSON.stringify({ messages }),

 { headers: { 'Content-Type': 'application/json' } });

 }



 async handleHistory(url) {

 const threadId = url.searchParams.get('threadId') || 'general';

 const limit = parseInt(url.searchParams.get('limit') || '100');

 const messages = await this.getThreadMessages(threadId, limit);

 return new Response(JSON.stringify({ messages }),

 { headers: { 'Content-Type': 'application/json' } });

 }



 async handleAgents() {

 const agents = this.sessions.map(s => ({ id: s.agentId, name: s.agentName, connectedAt: s.connectedAt }));

 return new Response(JSON.stringify({ agents }),

 { headers: { 'Content-Type': 'application/json' } });

 }



 async storeMessage(message) {

 const storage = await this.state.storage.get('messages') || [];

 storage.push(message);

 await this.state.storage.put('messages', storage);

 }



 async getMessagesSince(since) {

 const storage = await this.state.storage.get('messages') || [];

 return storage.filter(m => m.timestamp > since);

 }



 async getThreadMessages(threadId, limit) {

 const storage = await this.state.storage.get('messages') || [];

 return storage.filter(m => m.threadId === threadId).slice(-limit);

 }



 broadcast(message, excludeAgentId = null) {

 const data = JSON.stringify(message);

 this.sessions.forEach(session => {

 if (session.agentId !== excludeAgentId) {

 try { session.ws.send(data); } catch (err) { console.error('Broadcast error:', err); }

 }

 });

 }



 generateId() {

 return `${Date.now()}-${Math.random().toString(36).substr(2, 9)}`;

 }

}



